package com.example.packer;

import java.lang.reflect.Method;

/**
 * A miniature packer: the real behaviour lives in a DEX blob embedded in this
 * class, XOR-encrypted. The stub assembles the key, decrypts the blob, writes
 * it to the app's files dir, and installs a class loader over it — the same
 * shape real packers use, minus the native layer.
 */
public class Loader {

    // The encrypted payload. Regenerated by tools/make_fixtures.py.
    private static final byte[] BLOB = new byte[] {
        // BLOB_PLACEHOLDER
    };

    private static final byte[] KEY = new byte[] { 0x41, 0x4b, 0x37, 0x5a };

    public static byte[] decrypt(byte[] data, byte[] key) {
        byte[] out = new byte[data.length];
        for (int i = 0; i < data.length; i++) {
            out[i] = (byte) (data[i] ^ key[i % key.length]);
        }
        return out;
    }

    public static boolean looksLikeDex(byte[] b) {
        return b.length > 8 && b[0] == 'd' && b[1] == 'e' && b[2] == 'x' && b[3] == '\n';
    }

    public static void run(String filesDir) throws Exception {
        byte[] plain = decrypt(BLOB, KEY);
        if (!looksLikeDex(plain)) {
            return;
        }
        String path = filesDir + "/payload.dex";
        java.io.FileOutputStream fos = new java.io.FileOutputStream(path);
        fos.write(plain);
        fos.close();

        dalvik.system.DexClassLoader loader = new dalvik.system.DexClassLoader(
                path, filesDir, null, Loader.class.getClassLoader());
        Class<?> c = loader.loadClass("com.example.payload.Payload");
        Method m = c.getDeclaredMethod("execute", String.class);
        m.setAccessible(true);
        m.invoke(null, "arg-from-loader");
    }

    public static void main(String[] args) throws Exception {
        run("/data/data/com.example.packer/files");
    }
}
